<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; class InstalledVersion { private const SUFFIX = 'version'; private const MAX_MARKER = 4096; private const MAX_HISTORY = 65_536; public static function read(ServerFiles $files): ?array { return self::fromMarker($files) ?? self::detect($files); } public static function write(ServerFiles $files, array $record): bool { return \Pterodactyl\Services\Dezerx\Brand::write($files, '/', self::SUFFIX, json_encode($record + ['installedAt' => gmdate('c')], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) . "\n"); } private static function fromMarker(ServerFiles $files): ?array { $contents = \Pterodactyl\Services\Dezerx\Brand::read($files, '/', self::SUFFIX, self::MAX_MARKER); if ($contents === null) { return null; } $payload = json_decode($contents, true); if (!is_array($payload) || ($payload['version'] ?? '') === '') { return null; } return [ 'platform' => self::text($payload['platform'] ?? null), 'label' => self::text($payload['label'] ?? null), 'version' => self::text($payload['version'] ?? null), 'build' => self::text($payload['build'] ?? null), 'buildLabel' => self::text($payload['buildLabel'] ?? null), 'java' => (int) ($payload['java'] ?? 0), 'source' => 'panel', ]; } private static function detect(ServerFiles $files): ?array { return self::fromHistory($files) ?? self::fromLibraries($files); } private static function fromHistory(ServerFiles $files): ?array { $contents = $files->fileContents('/version_history.json', self::MAX_HISTORY); if ($contents === null) { return null; } $current = json_decode($contents, true)['currentVersion'] ?? null; if (!is_string($current) || $current === '') { return null; } if (preg_match('/^git-(\w+)-(\d+)\s+\(MC:\s*([\d.]+)\)/i', $current, $found) === 1) { return self::shape(mb_strtolower($found[1]), $found[1], $found[3], $found[2]); } if (preg_match('/^([\d.]+)-(\d+)-/', $current, $found) === 1) { return self::shape(null, null, $found[1], $found[2]); } return preg_match('/([\d.]+)/', $current, $found) === 1 ? self::shape(null, null, $found[1], null) : null; } private static function fromLibraries(ServerFiles $files): ?array { foreach ($files->listFiles('/libraries/net/minecraftforge/forge') ?? [] as $entry) { if (preg_match('/^([\d.]+)-([\d.]+)$/', (string) ($entry['name'] ?? ''), $found) === 1) { return self::shape('forge', 'Forge', $found[1], $found[2]); } } foreach ($files->listFiles('/libraries/net/neoforged/neoforge') ?? [] as $entry) { $build = (string) ($entry['name'] ?? ''); if (preg_match('/^(\d+)\.(\d+)\.\d+/', $build, $found) === 1) { $version = $found[2] === '0' ? '1.' . $found[1] : '1.' . $found[1] . '.' . $found[2]; return self::shape('neoforge', 'NeoForge', $version, $build); } } return null; } private static function shape(?string $platform, ?string $label, ?string $version, ?string $build): array { return [ 'platform' => $platform, 'label' => $label, 'version' => $version, 'build' => $build, 'buildLabel' => $build, 'java' => 0, 'source' => 'files', ]; } private static function text(mixed $value): ?string { $text = is_scalar($value) ? trim((string) $value) : ''; return $text === '' ? null : $text; } } 